import java.io.*;
import java.util.*;

public class E {
    void solver() throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        long n = readLong(dis);
        long[] ar = new long[3];
        ar[0] = readLong(dis); ar[1] = readLong(dis); ar[2] = readLong(dis);
        long[] br = new long[3];
        br[0] = readLong(dis); br[1] = readLong(dis); br[2] = readLong(dis);
        long maxWins = 0;
        long minNonWins = 0;
        long[] a = ar;
        long[] b = br;
        for (int i = 0; i < 3; i++) {
            long winAdd = a[i] < b[(i+1)%3] ? a[i] : b[(i+1)%3];
            maxWins = maxWins + winAdd;
            long loseMaybe = b[i] < a[(i+1)%3] ? b[i] : a[(i+1)%3];
            long drawMaybe = b[i] < a[i] ? b[i] : a[i];
            long sum = loseMaybe + drawMaybe;
            long cycleLose = b[i] < sum ? b[i] : sum;
            minNonWins = minNonWins + cycleLose;
        }
        System.out.println(String.valueOf(n - minNonWins) + " " + String.valueOf(maxWins));
    }

    private long readLong(DataInputStream dis) throws IOException {
        long result = 0;
        boolean negative = false;
        int c = dis.read();
        while (c <= 32) c = dis.read();
        if (c == '-') { negative = true; c = dis.read(); }
        while (c >= '0' && c <= '9') { result = result * 10 + (c - '0'); c = dis.read(); }
        if (negative) result = -result;
        return result;
    }

    public static void main(String[] args) throws IOException {
        new E().solver();
    }
}
